mapper.update:
UPDATE erp_bookstore_content
original_title = #{title}, author = #{author}, genre = #{genre}, content_type = #{contentType}, schoolyear = #{schoolYear}, summary = #{summary}, keywords = #{keywords}, state = #{state}, publisher = #{publisher}, image_url = #{imageUrl}, reading_time = #{readingTime}, difficulty = #{difficulty},
WHERE content_id = #{contentId}

MERGE erp_bookstore_content_detail AS target
USING (SELECT #{contentId, jdbcType=INTEGER} AS content_id, #{gubun, jdbcType=VARCHAR} AS gubun) AS source
ON target.content_id = source.content_id AND target.gubun = source.gubun
WHEN MATCHED THEN UPDATE SET name = #{name, jdbcType=VARCHAR}
WHEN NOT MATCHED THEN INSERT (content_id, gubun, name) VALUES (source.content_id, source.gubun, #{name, jdbcType=VARCHAR});

UPDATE erp_bookstore_item
book_title = #{bookTitle}, author = #{author}, publisher = #{publisher}, image_url = #{imageUrl},
WHERE bcode = #{bcode}

UPDATE erp_bookstore_item_center
quantity = #{quantity}, state = #{state},
WHERE bcode = #{bcode} AND center_code = #{centerCode}

UPDATE erp_bookstore_item_center
SET loaned_qty = CASE WHEN loaned_qty > 0 THEN loaned_qty - 1 ELSE 0 END
WHERE bcode = #{bcode} AND center_code = #{centerCode}
